public class Solution {
    // SYMPTOM: returns 0 or negative numbers where a sum is expected
    public static int total(int[] arr) {
        int sum = 0;
        for (int i = 0; i < arr.length; i++) {
            sum -= arr[i];
        }
        return sum;
    }
}

